//! Property tests for conversion over **well-typed** terms
//! (issues/kernel-conv-properties.md), generated by `common/wt.rs`:
//!
//! 1. the generator's triples pass `check_term` (the checker is the oracle
//!    for the generator — a failure here is a generator bug, isolating it
//!    from conversion bugs in the other tests);
//! 2. reflexivity `t ≈ t : T @ l` (the PER lemma of ch. 08, which the
//!    algorithmic checker must satisfy on well-typed inputs);
//! 3. `t ≈ whnf(t)` — conversion absorbs its own reduction relation;
//! 4. subject reduction, machine-checked: every `step_term` reduct still
//!    checks at the original type. Recursor β steps route `reduce.rs`'s
//!    `fire` instantiations through `typing.rs`'s `G_A` telescope checks —
//!    the cross-check of the hand-maintained tables the issue asks for;
//! 5. the identity recursor is the identity in one β-step on arbitrary
//!    generated code — `fire`'s payload wiring against all 22 branches.
//!
//! Failures report seeds only (`law!`); never Debug-format terms here.

mod common;

use heather_kernel::rc::Rc;

use common::wt::{
    gen_wt_ctx, gen_wt_env, gen_wt_term, gen_wt_type, identity_branches, identity_motives,
    FUEL,
};
use common::{law, Rng};
use heather_kernel::conv::conv_term;
use heather_kernel::layer::Layer;
use heather_kernel::level::Level;
use heather_kernel::reduce::{step_term, step_type, whnf_term};
use heather_kernel::term::{Term, Type};
use heather_kernel::typing::{check_global_ctx, check_local_ctx, check_term, check_type};

const CASES: u64 = 300;
const BUDGET: u32 = 8;

#[test]
fn generated_scopes_are_well_formed() {
    for seed in 0..CASES {
        let mut r = Rng::new(seed ^ 0x6c62272e07bb0142);
        let env = gen_wt_env(&mut r);
        assert!(
            check_global_ctx(&env.psi, env.univs, FUEL).is_ok(),
            "seed {seed}: generated Ψ ill-formed"
        );
        assert!(
            check_local_ctx(&env.psi, env.univs, env.layer, &env.gamma, FUEL).is_ok(),
            "seed {seed}: generated Γ ill-formed"
        );
    }
}

#[test]
fn generated_terms_type_check() {
    for seed in 0..CASES {
        let mut r = Rng::new(seed ^ 0xcbf29ce484222325);
        let env = gen_wt_env(&mut r);
        let (t, ty, l) = gen_wt_term(&env, &mut r, BUDGET);
        let res = check_term(&env.psi, env.univs, env.layer, &env.gamma, &t, &ty, &l, FUEL);
        assert!(res.is_ok(), "seed {seed}: generator produced ill-typed term: {res:?}");
    }
}

#[test]
fn conv_is_reflexive_on_well_typed_terms() {
    for seed in 0..CASES {
        let mut r = Rng::new(seed ^ 0x100000001b3);
        let env = gen_wt_env(&mut r);
        let (t, ty, l) = gen_wt_term(&env, &mut r, BUDGET);
        let at = env.layer.type_layer();
        let res = conv_term(&env.psi, &env.gamma, at, &t, &t, &ty, &l, FUEL);
        assert!(res.is_ok(), "seed {seed}: t ≉ t on a well-typed term: {res:?}");
    }
}

#[test]
fn conv_relates_term_to_its_whnf() {
    for seed in 0..CASES {
        let mut r = Rng::new(seed ^ 0xaf63bd4c8601b7df);
        let env = gen_wt_env(&mut r);
        let (t, ty, l) = gen_wt_term(&env, &mut r, BUDGET);
        let w = whnf_term(&t, &env.gamma, FUEL)
            .unwrap_or_else(|_| panic!("seed {seed}: well-typed term exhausted whnf fuel"));
        let at = env.layer.type_layer();
        // Both orientations: conversion is symmetric on well-typed inputs.
        let lr = conv_term(&env.psi, &env.gamma, at, &t, &w, &ty, &l, FUEL);
        assert!(lr.is_ok(), "seed {seed}: t ≉ whnf(t): {lr:?}");
        let rl = conv_term(&env.psi, &env.gamma, at, &w, &t, &ty, &l, FUEL);
        assert!(rl.is_ok(), "seed {seed}: whnf(t) ≉ t: {rl:?}");
    }
}

/// Preservation for **types**, the other half of DeLaM ch. 06's lemma:
/// *if `⊢_i T @ l` and `T ⇝ T'` then `⊢_i T' @ l`* — at the **same** `l`.
///
/// `reduction_preserves_type` below is the term half. There was no type half
/// until 2026-07-25, which is the whole reason `Vec^l(T;0) ⇝ Unit` could
/// drop a level unnoticed since phase 1: the generator was producing exactly
/// that witness all along (`gen_wt_type` takes `Vec`'s level from its element
/// and picks a small literal length two times in three), and nothing was
/// looking. With the check in place it fails on the first run, seed 102.
///
/// **The gap this found is closed** as of route (a)
/// (`docs/kernel/unit-empty-level-indexing.md`): `Vec^l(T;0) ⇝ Unit^l` now carries
/// its level, so the narrow skip that used to sit here — only this reduct,
/// only `LevelMismatch` — is gone and the law runs unconditionally.
#[test]
fn type_reduction_preserves_level() {
    for seed in 0..CASES {
        let mut r = Rng::new(seed ^ 0x84222325cbf29ce4);
        let env = gen_wt_env(&mut r);
        let (ty, l) = gen_wt_type(&env, &mut r, BUDGET);
        let mut cur = (*ty).clone();
        for _ in 0..16 {
            let Some(next) = step_type(&cur, &env.gamma).expect("a generated type steps within the frame budget") else { break };
            let res = check_type(&env.psi, env.univs, env.layer, &env.gamma, &next, &l, FUEL);
            assert!(res.is_ok(), "seed {seed}: type preservation violated: {res:?}");
            cur = next;
        }
    }
}

#[test]
fn reduction_preserves_type() {
    for seed in 0..CASES {
        let mut r = Rng::new(seed ^ 0x9ae16a3b2f90404f);
        let env = gen_wt_env(&mut r);
        let (t, ty, l) = gen_wt_term(&env, &mut r, BUDGET);
        let mut cur = (*t).clone();
        for _ in 0..16 {
            let Some(next) = step_term(&cur, &env.gamma).expect("a generated term steps within the frame budget") else { break };
            let res =
                check_term(&env.psi, env.univs, env.layer, &env.gamma, &next, &ty, &l, FUEL);
            // Reduction can create a meta-level β-redex whose body is a bare
            // `box` (e.g. `app(λx. Λg. x; box T)` ⇝ `Λg. box T` under an
            // application head): declaratively typable but algorithmically
            // NotInferable — the box synthesis gap
            // (issues/box-synthesis-gap.md), not a subject-reduction bug.
            if res == Err(heather_kernel::typing::TypeError::NotInferable) {
                break;
            }
            assert!(res.is_ok(), "seed {seed}: subject reduction violated: {res:?}");
            cur = next;
        }
    }
}

#[test]
fn identity_recursor_is_identity_on_code_of_types() {
    for seed in 0..CASES {
        let mut r = Rng::new(seed ^ 0xc3a5c85c97cb3127);
        let mut env = gen_wt_env(&mut r);
        env.layer = Layer::Meta; // recursors are layer-m forms
        let delta = gen_wt_ctx(&env, &mut r, 4, Layer::Code);
        let ce = env.in_ctx(delta.clone(), Layer::Code);
        let (code, cl) = gen_wt_type(&ce, &mut r, 4);
        let t = Term::ElimCodeTy {
            ty_motive_level: Level::Zero,
            tm_motive_level: Level::Zero,
            motives: identity_motives(),
            branches: identity_branches(),
            code_level: cl.clone(),
            ctx: delta.clone(),
            scrut: Rc::new(Term::BoxTy(Rc::clone(&code))),
        };
        let expect = Type::CodeTy { ctx: delta, level: cl };
        let res = check_term(
            &env.psi, env.univs, env.layer, &env.gamma, &t, &expect, &Level::Zero, FUEL,
        );
        assert!(res.is_ok(), "seed {seed}: identity elim^Typ ill-typed: {res:?}");
        let w = whnf_term(&t, &env.gamma, FUEL)
            .unwrap_or_else(|_| panic!("seed {seed}: identity elim^Typ exhausted fuel"));
        if matches!(&*code, Type::GlobalTy { .. }) {
            // box (U^δ) blocks: the recursor is neutral.
            law!(seed, w, t);
        } else {
            law!(seed, w, Term::BoxTy(code));
        }
    }
}

#[test]
fn identity_recursor_is_identity_on_code_of_terms() {
    for seed in 0..CASES {
        let mut r = Rng::new(seed ^ 0xff51afd7ed558ccd);
        let mut env = gen_wt_env(&mut r);
        env.layer = Layer::Meta;
        let delta = gen_wt_ctx(&env, &mut r, 4, Layer::Code);
        let ce = env.in_ctx(delta.clone(), Layer::Code);
        let (code, cty, cl) = gen_wt_term(&ce, &mut r, 4);
        let t = Term::ElimCodeTm {
            ty_motive_level: Level::Zero,
            tm_motive_level: Level::Zero,
            motives: identity_motives(),
            branches: identity_branches(),
            code_level: cl.clone(),
            ctx: delta.clone(),
            ty: Rc::clone(&cty),
            scrut: Rc::new(Term::BoxTm(Rc::clone(&code))),
        };
        let expect = Type::CodeTm { ctx: delta, ty: cty, level: cl };
        let res = check_term(
            &env.psi, env.univs, env.layer, &env.gamma, &t, &expect, &Level::Zero, FUEL,
        );
        assert!(res.is_ok(), "seed {seed}: identity elim^Trm ill-typed: {res:?}");
        let w = whnf_term(&t, &env.gamma, FUEL)
            .unwrap_or_else(|_| panic!("seed {seed}: identity elim^Trm exhausted fuel"));
        if matches!(&*code, Term::GlobalTm { .. }) {
            // Blocked on box (u^δ); only the type annotation may have
            // stepped, so compare against the term's own WHNF fixpoint by
            // checking it no longer steps and stays convertible.
            assert!(matches!(step_term(&w, &env.gamma), Ok(None)), "seed {seed}: neutral still steps");
        } else {
            law!(seed, w, Term::BoxTm(code));
        }
    }
}
